def now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def posthog_configured() -> bool:
    return bool(
        POSTHOG_PROJECT_TOKEN
        and POSTHOG_HOST.startswith(("https://", "http://127.0.0.1", "http://localhost"))
    )


def analytics_organization_key(organization_id: str | None) -> str:
    if not organization_id:
        return ""
    return hashlib.sha256(f"{PRODUCT_ID}:{organization_id}".encode("utf-8")).hexdigest()[:24]


def send_posthog_event(
    event_name: str,
    distinct_id: str,
    properties: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if not posthog_configured():
        return {"passed": False, "status": "not_configured", "status_code": None}
    event_properties = {
        "product_id": PRODUCT_ID,
        "build_id": PRODUCT_BUILD_ID,
        "release_sha": PRODUCT_RELEASE_SHA,
        "environment": os.environ.get("PRODUCT_ENV", "development"),
        "telemetry_source": "server",
        **(properties or {}),
    }
    body = json.dumps({
        "api_key": POSTHOG_PROJECT_TOKEN,
        "event": event_name,
        "distinct_id": distinct_id or f"product:{PRODUCT_ID}",
        "properties": event_properties,
        "timestamp": now(),
    }).encode("utf-8")
    request = Request(
        f"{POSTHOG_HOST}/i/v0/e/",
        data=body,
        headers={"Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urlopen(request, timeout=float(os.environ.get("POSTHOG_TIMEOUT_SECONDS", "3"))) as response:
            return {
                "passed": 200 <= response.status < 300,
                "status": "accepted" if 200 <= response.status < 300 else "rejected",
                "status_code": response.status,
            }
    except HTTPError as exc:
        return {"passed": False, "status": "rejected", "status_code": exc.code}
    except (OSError, URLError, ValueError):
        return {"passed": False, "status": "unavailable", "status_code": None}


def capture_product_event(
    event_name: str,
    actor: dict[str, Any] | None = None,
    properties: dict[str, Any] | None = None,
) -> dict[str, Any]:
    actor = actor or {}
    organization_key = analytics_organization_key(str(actor.get("organization_id") or ""))
    event_properties = {**(properties or {})}
    if organization_key:
        event_properties["organization_key"] = organization_key
    if not posthog_configured():
        return {"passed": False, "status": "not_configured", "status_code": None}
    threading.Thread(
        target=send_posthog_event,
        args=(event_name, str(actor.get("user_id") or f"product:{PRODUCT_ID}"), event_properties),
        daemon=True,
    ).start()
    return {"passed": True, "status": "queued", "status_code": None}


def reject_legacy_mutation_if_executable() -> None:
    if EXECUTABLE_PRODUCT:
        raise HTTPException(status_code=410, detail="Use the typed /commands/{command_id} endpoint for this product")


def db_enabled() -> bool:
    return DATABASE_URL.startswith(("postgres://", "postgresql://"))


def ensure_db() -> None:
    global DB_READY
    if not db_enabled():
        return
    if DB_READY:
        return
    import psycopg
    from psycopg.types.json import Jsonb

    with psycopg.connect(DATABASE_URL) as conn:
        conn.execute("""
            create table if not exists product_states (
              organization_id text not null,
              product_id text not null,
              state jsonb not null,
              updated_at timestamptz not null default now(),
              primary key (organization_id, product_id)
            )
        """)
        conn.execute(
            """
            insert into product_states (organization_id, product_id, state)
            values (%s, %s, %s)
            on conflict (organization_id, product_id) do nothing
            """,
            ("org_local", PRODUCT_ID, Jsonb(SEED_STATE)),
        )
        conn.execute("""
            create table if not exists public_directory_items (
              product_id text not null,
              item_id text not null,
              item_name text not null,
              postal_code text not null,
              postal_prefix text not null,
              latitude double precision,
              longitude double precision,
              source_kind text not null default 'seed',
              origin text not null default 'seed',
              payload jsonb not null,
              updated_at timestamptz not null default now(),
              primary key (product_id, item_id)
            )
        """)
        conn.execute("""
            create index if not exists public_directory_items_product_postal_idx
            on public_directory_items (product_id, postal_prefix, postal_code)
        """)
        rows = [
            (
                PRODUCT_ID,
                str(item.get("id") or ""),
                str(item.get("name") or "Directory item"),
                str(item.get("postal_code") or ""),
                str(item.get("postal_prefix") or str(item.get("postal_code") or "")[:3]),
                item.get("latitude"),
                item.get("longitude"),
                str(item.get("source_kind") or "seed"),
                Jsonb(item),
            )
            for item in PUBLIC_DIRECTORY_ITEMS
            if item.get("id") and item.get("postal_code")
        ]
        if rows:
            with conn.cursor() as cursor:
                cursor.executemany(
                    """
                    insert into public_directory_items (
                      product_id, item_id, item_name, postal_code, postal_prefix,
                      latitude, longitude, source_kind, origin, payload, updated_at
                    ) values (%s, %s, %s, %s, %s, %s, %s, %s, 'seed', %s, now())
                    on conflict (product_id, item_id) do update set
                      item_name=excluded.item_name,
                      postal_code=excluded.postal_code,
                      postal_prefix=excluded.postal_prefix,
                      latitude=excluded.latitude,
                      longitude=excluded.longitude,
                      source_kind=excluded.source_kind,
                      payload=excluded.payload,
                      updated_at=now()
                    where public_directory_items.origin='seed'
                    """,
                    rows,
                )
        seed_ids = [str(item.get("id")) for item in PUBLIC_DIRECTORY_ITEMS if item.get("id")]
        if seed_ids:
            conn.execute(
                """
                delete from public_directory_items
                where product_id=%s and origin='seed' and not (item_id = any(%s))
                """,
                (PRODUCT_ID, seed_ids),
            )
        else:
            conn.execute(
                "delete from public_directory_items where product_id=%s and origin='seed'",
                (PRODUCT_ID,),
            )
    DB_READY = True


def load_state(organization_id: str) -> dict[str, Any]:
    if not db_enabled():
        return normalize_state(STATE.setdefault(organization_id, copy.deepcopy(SEED_STATE)))
    import psycopg

    ensure_db()
    with psycopg.connect(DATABASE_URL) as conn:
        row = conn.execute(
            "select state from product_states where organization_id=%s and product_id=%s",
            (organization_id, PRODUCT_ID),
        ).fetchone()
    if row is None:
        return copy.deepcopy(SEED_STATE)
    return normalize_state(dict(row[0]))


def normalize_state(state: dict[str, Any]) -> dict[str, Any]:
    state.setdefault("entities", [])
    state.setdefault("records", [])
    state.setdefault("resources", {})
    state.setdefault("activity", [])
    state.setdefault("feedback", [])
    state.setdefault("pilot_intakes", [])
    state.setdefault("billing_events", [])
    state.setdefault("command_receipts", {})
    state.setdefault("settings", copy.deepcopy(SEED_STATE.get("settings", {})))
    state.setdefault("business_model", SEED_STATE.get("business_model", {}))
    return state


def save_state(organization_id: str, state: dict[str, Any]) -> None:
    state = normalize_state(state)
    if not db_enabled():
        STATE[organization_id] = state
        return
    import psycopg
    from psycopg.types.json import Jsonb

    ensure_db()
    with psycopg.connect(DATABASE_URL) as conn:
        conn.execute(
            """
            insert into product_states (organization_id, product_id, state, updated_at)
            values (%s, %s, %s, now())
            on conflict (organization_id, product_id)
            do update set state=excluded.state, updated_at=now()
            """,
            (organization_id, PRODUCT_ID, Jsonb(state)),
        )


def inkpass_userinfo_url() -> str:
    explicit = os.environ.get("INKPASS_USERINFO_URL", "").strip()
    if explicit:
        return explicit
    base = os.environ.get("INKPASS_URL", "").strip().rstrip("/")
    return f"{base}/api/v1/auth/me" if base else ""


def inkpass_base_url() -> str:
    base = os.environ.get("INKPASS_URL", "").strip().rstrip("/")
    if not base.startswith("https://") and not base.startswith("http://127.0.0.1") and not base.startswith("http://localhost"):
        raise InkPassAuthError("InkPass URL must be configured")
    return base


def inkpass_client_slug(requested: str | None = None) -> str:
    value = (requested or os.environ.get("INKPASS_CLIENT_SLUG") or os.environ.get("PRODUCT_INKPASS_CLIENT_SLUG") or 'quote-intake-demo').strip()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{1,80}", value):
        raise InkPassAuthError("InkPass client slug is invalid")
    return value


def post_inkpass_json(path: str, payload: dict[str, Any]) -> dict[str, Any]:
    body = json.dumps(payload).encode("utf-8")
    request = Request(
        f"{inkpass_base_url()}{path}",
        data=body,
        headers={"Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urlopen(request, timeout=float(os.environ.get("INKPASS_TIMEOUT_SECONDS", "8"))) as response:
            return json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        text = exc.read().decode("utf-8", errors="replace")
        try:
            detail = json.loads(text).get("detail", text)
        except json.JSONDecodeError:
            detail = text
        if exc.code in {400, 401, 403, 404, 422, 429}:
            raise HTTPException(status_code=exc.code, detail=detail) from exc
        raise InkPassAuthError(f"InkPass request failed with {exc.code}") from exc
    except (OSError, URLError, ValueError, json.JSONDecodeError) as exc:
        raise InkPassAuthError("InkPass request unavailable") from exc


def session_from_inkpass_token(token: str) -> dict[str, str]:
    actor = verify_inkpass_token(token)
    return {
        "token": token,
        "organization_id": actor["organization_id"],
        "user_id": actor["user_id"],
        "auth_provider": "inkpass",
    }


def verify_inkpass_token(token: str) -> dict[str, str]:
    endpoint = inkpass_userinfo_url()
    service_key = os.environ.get("PRODUCT_INKPASS_SERVICE_API_KEY") or os.environ.get("INKPASS_SERVICE_API_KEY") or ""
    if not endpoint.startswith("https://") and not endpoint.startswith("http://127.0.0.1") and not endpoint.startswith("http://localhost"):
        raise InkPassAuthError("InkPass userinfo endpoint must be configured")
    if not service_key:
        raise InkPassAuthError("InkPass service API key must be configured")
    request = Request(
        endpoint,
        headers={"Authorization": f"Bearer {token}", "X-Service-API-Key": service_key, "Accept": "application/json"},
        method="GET",
    )
    try:
        with urlopen(request, timeout=float(os.environ.get("INKPASS_TIMEOUT_SECONDS", "5"))) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except HTTPError as exc:
        if exc.code in {401, 403}:
            raise HTTPException(status_code=401, detail="Invalid InkPass token") from exc
        raise InkPassAuthError(f"InkPass userinfo failed with {exc.code}") from exc
    except (OSError, URLError, ValueError, json.JSONDecodeError) as exc:
        raise InkPassAuthError("InkPass userinfo unavailable") from exc
    organization_id = str(payload.get("organization_id") or payload.get("org_id") or "")
    user_id = str(payload.get("user_id") or payload.get("sub") or payload.get("id") or "")
    if not organization_id or not user_id:
        raise InkPassAuthError("InkPass userinfo missing organization or user id")
    return {"organization_id": organization_id, "user_id": user_id, "token": token}


def check_inkpass_permission(token: str, resource: str, action: str) -> bool:
    if not token:
        return False
    body = json.dumps({}).encode("utf-8")
    request = Request(
        f"{inkpass_base_url()}/api/v1/auth/check?resource={resource}&action={action}",
        data=body,
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urlopen(request, timeout=float(os.environ.get("INKPASS_TIMEOUT_SECONDS", "5"))) as response:
            payload = json.loads(response.read().decode("utf-8"))
            return bool(payload.get("has_permission") or payload.get("allowed"))
    except HTTPError as exc:
        if exc.code in {401, 403}:
            return False
        raise InkPassAuthError(f"InkPass permission check failed with {exc.code}") from exc
    except (OSError, URLError, ValueError, json.JSONDecodeError) as exc:
        raise InkPassAuthError("InkPass permission check unavailable") from exc


def require_permission(actor: dict[str, Any], permission: str) -> None:
    if actor.get("user_id") == "product_factory_agent":
        return
    if permission in actor.get("permissions", []):
        return
    if os.environ.get("PRODUCT_ENV") == "production":
        try:
            if check_inkpass_permission(actor.get("token", ""), PRODUCT_ID, permission):
                return
        except InkPassAuthError as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc
    raise HTTPException(status_code=403, detail=f"Permission required: {permission}")


def require_owner_report(actor: dict[str, str]) -> None:
    if actor.get("user_id") == "product_factory_agent":
        return
    if os.environ.get("PRODUCT_ENV") == "production":
        try:
            if check_inkpass_permission(actor.get("token", ""), "product_owner", "read"):
                return
        except InkPassAuthError as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc
    raise HTTPException(status_code=403, detail="Owner report requires InkPass RBAC permission product_owner:read")


def demo_access_secret() -> str:
    return os.environ.get("PRODUCT_DEMO_ACCESS_TOKEN", "").strip()


def issue_demo_session_token() -> str:
    secret = demo_access_secret() or "local-demo-session-secret"
    payload = f"{int(time.time()) + 28800}.{uuid4().hex}"
    signature = hmac.new(secret.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()
    return f"demo.{payload}.{signature}"


def verify_demo_session_token(token: str) -> bool:
    secret = demo_access_secret() or ("local-demo-session-secret" if os.environ.get("PRODUCT_ENV") != "production" else "")
    if not secret:
        return False
    parts = token.split(".")
    if len(parts) != 4 or parts[0] != "demo":
        return False
    payload = f"{parts[1]}.{parts[2]}"
    expected = hmac.new(secret.encode("utf-8"), payload.encode("utf-8"), hashlib.sha256).hexdigest()
    try:
        return int(parts[1]) >= int(time.time()) and hmac.compare_digest(expected, parts[3])
    except ValueError:
        return False


def subject(
    authorization: str | None = Header(default=None),
    x_api_key: str | None = Header(default=None, alias="X-API-Key"),
) -> dict[str, str]:
    service_key = os.environ.get("PRODUCT_INKPASS_SERVICE_API_KEY") or os.environ.get("INKPASS_SERVICE_API_KEY") or ""
    if service_key and x_api_key and x_api_key == service_key:
        return {"organization_id": "org_product_factory_agent", "user_id": "product_factory_agent", "token": "", "persona_id": "service", "permissions": ["*"]}
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing bearer token")
    token = authorization.removeprefix("Bearer ").strip()
    if token.startswith("demo."):
        if verify_demo_session_token(token):
            return {"organization_id": "org_product_demo", "user_id": "demo_user", "token": token, "persona_id": DEFAULT_PERSONA_ID, "permissions": ROLE_PERMISSIONS.get(DEFAULT_PERSONA_ID, [])}
        raise HTTPException(status_code=401, detail="Invalid or expired demo token")
    if os.environ.get("PRODUCT_ENV") == "production":
        if os.environ.get("INKPASS_AUTH_MODE") != "inkpass":
            raise HTTPException(status_code=503, detail="InkPass auth is required in production")
        if token.startswith("local."):
            raise HTTPException(status_code=401, detail="Local auth tokens are disabled in production")
        try:
            return verify_inkpass_token(token)
        except HTTPException:
            raise
        except InkPassAuthError as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc
    if not token.startswith("local."):
        raise HTTPException(status_code=401, detail="Invalid token")
    parts = token.split(".", 2)
    persona_id = parts[1] if len(parts) == 3 else DEFAULT_PERSONA_ID
    if persona_id not in ROLE_PERMISSIONS and ROLE_PERMISSIONS:
        raise HTTPException(status_code=401, detail="Unknown local persona")
    return {"organization_id": "org_local", "user_id": f"user_{persona_id}", "token": token, "persona_id": persona_id, "permissions": ROLE_PERMISSIONS.get(persona_id, [])}


