@app.get("/public/directory")
def public_directory(postal_code: str | None = None, limit: int = 1000) -> dict[str, Any]:
    if not PUBLIC_HOMEPAGE_ENABLED:
        raise HTTPException(status_code=404, detail="Public directory is unavailable")
    postal = (postal_code or "").strip()
    if postal and not re.fullmatch(r"\d{5}", postal):
        raise HTTPException(status_code=422, detail="postal_code must be a 5-digit ZIP code")
    safe_limit = min(max(int(limit), 1), 1000)
    if not db_enabled():
        items = list(PUBLIC_DIRECTORY_ITEMS)
        if postal:
            prefix = postal[:3]
            items = [
                item for item in items
                if str(item.get("postal_code") or "") == postal
                or str(item.get("postal_prefix") or "") == prefix
            ]
            items.sort(key=lambda item: (str(item.get("postal_code") or "") != postal, str(item.get("name") or "").casefold()))
        else:
            items.sort(key=lambda item: (str(item.get("postal_code") or ""), str(item.get("name") or "").casefold()))
        return {"items": items[:safe_limit], "total": len(items), "postal_code": postal or None}

    import psycopg

    ensure_db()
    with psycopg.connect(DATABASE_URL) as conn:
        if postal:
            prefix = postal[:3]
            total = conn.execute(
                """
                select count(*) from public_directory_items
                where product_id=%s and postal_prefix=%s
                """,
                (PRODUCT_ID, prefix),
            ).fetchone()[0]
            rows = conn.execute(
                """
                select payload from public_directory_items
                where product_id=%s and postal_prefix=%s
                order by (postal_code=%s) desc, lower(item_name), item_id
                limit %s
                """,
                (PRODUCT_ID, prefix, postal, safe_limit),
            ).fetchall()
        else:
            total = conn.execute(
                "select count(*) from public_directory_items where product_id=%s",
                (PRODUCT_ID,),
            ).fetchone()[0]
            rows = conn.execute(
                """
                select payload from public_directory_items
                where product_id=%s
                order by postal_code, lower(item_name), item_id
                limit %s
                """,
                (PRODUCT_ID, safe_limit),
            ).fetchall()
    return {"items": [dict(row[0]) for row in rows], "total": int(total), "postal_code": postal or None}


@app.post("/auth/local-session")
def local_session(payload: SessionRequest) -> dict[str, Any]:
    if os.environ.get("PRODUCT_ENV") == "production":
        raise HTTPException(status_code=404, detail="Local auth simulation is disabled in production")
    if payload.product_id != PRODUCT_ID:
        raise HTTPException(status_code=400, detail="Wrong product")
