@app.post("/auth/demo-session")
def demo_session(payload: SessionRequest) -> dict[str, str]:
    if payload.product_id != PRODUCT_ID:
        raise HTTPException(status_code=400, detail="Wrong product")
    if os.environ.get("PRODUCT_ENV") == "production":
        secret = demo_access_secret()
        supplied = (payload.access_token or "").strip()
        if not secret or not supplied or not hmac.compare_digest(secret, supplied):
            raise HTTPException(status_code=404, detail="Demo access is unavailable")
    return {"token": issue_demo_session_token(), "organization_id": "org_product_demo", "user_id": "demo_user"}


@app.post("/auth/inkpass/login")
def inkpass_login(payload: InkPassLoginRequest) -> dict[str, str]:
    try:
        slug = inkpass_client_slug(payload.client_slug)
        request_payload = {"email": payload.email, "password": payload.password}
        if payload.two_fa_code:
            request_payload["two_fa_code"] = payload.two_fa_code
        result = post_inkpass_json(f"/api/v1/auth/clients/{slug}/login", request_payload)
        token = str(result.get("access_token") or "")
        if not token:
            raise InkPassAuthError("InkPass login did not return an access token")
        session = session_from_inkpass_token(token)
        capture_product_event("product_login_completed", session, {"auth_provider": "inkpass"})
        return session
    except HTTPException:
        raise
    except InkPassAuthError as exc:
        raise HTTPException(status_code=503, detail=str(exc)) from exc


