@app.post("/public/pilot-intake")
def submit_pilot_intake(payload: PilotIntakeRequest) -> dict[str, Any]:
    email = payload.email.strip().lower()
    message = payload.message.strip()
    if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
        raise HTTPException(status_code=422, detail="A valid email is required")
    if len(message) < 8:
        raise HTTPException(status_code=422, detail="Pilot intake message must describe the workflow")
    status = (payload.paid_pilot_status or "pre_checkout").strip().lower()
    if status not in {"pre_checkout", "checkout_success", "paid", "unknown"}:
        status = "unknown"
    state = load_state("org_public_intake")
    item = {
        "intake_id": f"pilot_intake_{uuid4().hex[:12]}",
        "email": email,
        "name": (payload.name or "").strip(),
        "organization_name": (payload.organization_name or "").strip(),
        "message": message[:2000],
        "paid_pilot_status": status,
        "source": "public_pilot_intake",
        "created_at": now(),
    }
    state["pilot_intakes"].append(item)
    state["activity"].append({"event_name": "paid_pilot_intake_submitted", "intake_id": item["intake_id"], "paid_pilot_status": status, "created_at": now()})
    save_state("org_public_intake", state)
    capture_product_event(
        "paid_pilot_intake_submitted",
        properties={"paid_pilot_status": status, "intake_id": item["intake_id"]},
    )
    return {"received": True, "intake": item}


def stripe_webhook_secret() -> str:
    return (os.environ.get("PRODUCT_STRIPE_WEBHOOK_SECRET") or os.environ.get("STRIPE_WEBHOOK_SECRET") or "").strip()


def verify_stripe_signature(body: bytes, signature_header: str | None) -> None:
    secret = stripe_webhook_secret()
    if not secret:
        raise HTTPException(status_code=503, detail="Stripe webhook secret is not configured")
    if not signature_header:
        raise HTTPException(status_code=400, detail="Missing Stripe signature")
    parts = {}
    for item in signature_header.split(","):
        if "=" in item:
            key, value = item.split("=", 1)
            parts.setdefault(key, []).append(value)
    timestamp_values = parts.get("t") or []
    signatures = parts.get("v1") or []
    if not timestamp_values or not signatures:
        raise HTTPException(status_code=400, detail="Invalid Stripe signature header")
    timestamp = timestamp_values[0]
    try:
        if abs(time.time() - int(timestamp)) > 300:
            raise HTTPException(status_code=400, detail="Stripe signature timestamp is outside tolerance")
    except ValueError as exc:
        raise HTTPException(status_code=400, detail="Invalid Stripe signature timestamp") from exc
    signed_payload = timestamp.encode("utf-8") + b"." + body
    expected = hmac.new(secret.encode("utf-8"), signed_payload, hashlib.sha256).hexdigest()
    if not any(hmac.compare_digest(expected, signature) for signature in signatures):
        raise HTTPException(status_code=400, detail="Invalid Stripe signature")


def expected_payment_link_id() -> str:
    business_model = SEED_STATE.get("business_model", {})
    return str(business_model.get("payment_link_id") or business_model.get("stripe_payment_link_id") or "").strip()


def stripe_payment_event(event: dict[str, Any]) -> dict[str, Any]:
    event_type = str(event.get("type") or "")
    data = event.get("data") if isinstance(event.get("data"), dict) else {}
    obj = data.get("object") if isinstance(data.get("object"), dict) else {}
    metadata = obj.get("metadata") if isinstance(obj.get("metadata"), dict) else {}
    payment_intent = obj.get("payment_intent") if isinstance(obj.get("payment_intent"), dict) else {}
    payment_intent_metadata = payment_intent.get("metadata") if isinstance(payment_intent.get("metadata"), dict) else {}
    combined_metadata = {**payment_intent_metadata, **metadata}
    configured_payment_link = expected_payment_link_id()
    payment_link = str(obj.get("payment_link") or combined_metadata.get("payment_link") or "")
    metadata_product_id = str(combined_metadata.get("product_id") or combined_metadata.get("product_factory_product_id") or "")
    metadata_build_id = str(combined_metadata.get("build_id") or combined_metadata.get("product_factory_build_id") or "")
    matches_product = metadata_product_id == PRODUCT_ID or bool(configured_payment_link and payment_link == configured_payment_link)
    amount_cents = obj.get("amount_total")
    if amount_cents is None:
        amount_cents = obj.get("amount_received")
    if amount_cents is None:
        amount_cents = obj.get("amount")
    if amount_cents is None:
        amount_cents = obj.get("amount_captured")
    if not isinstance(amount_cents, int):
        amount_cents = 0
    return {
        "event_id": str(event.get("id") or f"stripe_event_{uuid4().hex[:12]}"),
        "event_type": event_type,
        "livemode": bool(event.get("livemode")),
        "object_id": str(obj.get("id") or ""),
        "checkout_session_id": str(obj.get("id") or "") if event_type.startswith("checkout.session.") else "",
        "payment_intent_id": str(payment_intent.get("id") or obj.get("payment_intent") or ""),
        "payment_link_id": payment_link,
        "amount_cents": amount_cents,
        "currency": str(obj.get("currency") or "").lower(),
        "payment_status": str(obj.get("payment_status") or obj.get("status") or ""),
        "metadata_product_id": metadata_product_id,
        "metadata_build_id": metadata_build_id,
        "matches_product": matches_product,
        "source": "stripe_webhook",
        "created_at": now(),
    }


def is_settled_live_payment(payment_event: dict[str, Any]) -> bool:
    business_model = SEED_STATE.get("business_model", {})
    expected_amount = business_model.get("paid_pilot_amount_cents")
    expected_currency = str(business_model.get("paid_pilot_currency") or "").lower()
    event_type = str(payment_event.get("event_type") or "")
    payment_status = str(payment_event.get("payment_status") or "").lower()
    settled_status = (
        event_type in {"checkout.session.completed", "checkout.session.async_payment_succeeded"}
        and payment_status == "paid"
    ) or (event_type == "payment_intent.succeeded" and payment_status == "succeeded")
    return bool(
        payment_event.get("livemode") is True
        and settled_status
        and isinstance(expected_amount, int)
        and payment_event.get("amount_cents") == expected_amount
        and expected_currency
        and payment_event.get("currency") == expected_currency
    )


@app.post("/webhooks/stripe")
async def stripe_webhook(request: FastAPIRequest, stripe_signature: str | None = Header(default=None, alias="Stripe-Signature")) -> dict[str, Any]:
    body = await request.body()
    verify_stripe_signature(body, stripe_signature)
    try:
        event = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise HTTPException(status_code=400, detail="Stripe webhook body must be JSON") from exc
    if not isinstance(event, dict):
        raise HTTPException(status_code=400, detail="Stripe webhook body must be a JSON object")
    payment_event = stripe_payment_event(event)
    accepted = bool(payment_event["matches_product"] and is_settled_live_payment(payment_event))
    payment_event["settled_live_payment"] = accepted
    state = load_state("org_public_intake")
    existing_event_ids = {str(item.get("event_id")) for item in state.get("billing_events", []) if isinstance(item, dict)}
    duplicate = payment_event["event_id"] in existing_event_ids
    if not duplicate:
        state["billing_events"].append(payment_event)
        state["activity"].append({
            "event_name": "paid_pilot_payment_received" if accepted else "stripe_payment_event_ignored",
            "stripe_event_id": payment_event["event_id"],
            "event_type": payment_event["event_type"],
            "matches_product": payment_event["matches_product"],
            "settled_live_payment": accepted,
            "amount_cents": payment_event["amount_cents"],
            "created_at": now(),
        })
        save_state("org_public_intake", state)
        capture_product_event(
            "paid_pilot_payment_received" if accepted else "stripe_payment_event_ignored",
            properties={
                "event_id": payment_event["event_id"],
                "event_type": payment_event["event_type"],
                "settled_live_payment": accepted,
                "amount_cents": payment_event["amount_cents"],
                "currency": payment_event["currency"],
            },
        )
    return {
        "received": True,
        "accepted": accepted,
        "duplicate": duplicate,
        "event_id": payment_event["event_id"],
        "event_type": payment_event["event_type"],
    }


@app.post("/feedback")
def submit_feedback(payload: FeedbackRequest, actor: dict[str, str] = Depends(subject)) -> dict[str, Any]:
    state = load_state(actor["organization_id"])
    severity = payload.severity if payload.severity in {"low", "medium", "high", "critical"} else "medium"
    item = {
        "feedback_id": f"feedback_{uuid4().hex[:12]}",
        "workflow": payload.workflow or "",
        "severity": severity,
        "message": payload.message,
        "willingness_to_pay": payload.willingness_to_pay,
        "lost_time_minutes": payload.lost_time_minutes,
        "user_id": actor["user_id"],
        "organization_id": actor["organization_id"],
        "created_at": now(),
    }
    state["feedback"].append(item)
    state["activity"].append({"event_name": "customer_feedback_submitted", "feedback_id": item["feedback_id"], "severity": severity, "user_id": actor["user_id"], "created_at": now()})
    save_state(actor["organization_id"], state)
    capture_product_event(
        "customer_feedback_submitted",
        actor,
        {"feedback_id": item["feedback_id"], "severity": severity, "workflow": item["workflow"]},
    )
