@app.post("/verification/workflow")
def verify_production_workflow(actor: dict[str, str] = Depends(subject)) -> dict[str, Any]:
    if actor.get("user_id") != "product_factory_agent":
        raise HTTPException(status_code=403, detail="Production verification requires the product service key")
    state = load_state(actor["organization_id"])
    record = next(
        (
            item
            for item in state["records"]
            if item.get("type") == "production_verification"
        ),
        None,
    )
    if record is None:
        record = {
            "id": f"verification_{uuid4().hex[:12]}",
            "name": "Product Factory live verification",
            "type": "production_verification",
            "entity": PRODUCT_ID,
            "status": "draft",
            "created_at": now(),
        }
        state["records"].append(record)
    already_completed = record.get("status") == "completed"
    if not already_completed:
        record["status"] = "completed"
        state["activity"].append({"event_name": 'quote_intake_demo_workflow_completed', "record_id": record["id"], "user_id": actor["user_id"], "created_at": now()})
        state["activity"].append({"event_name": 'sandbox_billable_quote_intake_demo_workflow_completed', "record_id": record["id"], "amount_usd": '360.00', "created_at": now()})
        save_state(actor["organization_id"], state)
        capture_product_event('quote_intake_demo_workflow_completed', actor, {"record_id": record["id"], "verification": True})
        capture_product_event('sandbox_billable_quote_intake_demo_workflow_completed', actor, {"record_id": record["id"], "amount_usd": '360.00', "verification": True})
    return {
        "state": state,
        "record_id": record["id"],
        "already_completed": already_completed,
        "database": "postgres" if db_enabled() else "memory",
    }


@app.post("/records")
def create_record(payload: RecordCreate, actor: dict[str, str] = Depends(subject)) -> dict[str, Any]:
    reject_legacy_mutation_if_executable()
    state = load_state(actor["organization_id"])
    name = payload.name.strip()
    if len(name) < 3:
        raise HTTPException(status_code=422, detail="Record name must contain at least 3 characters")
    record = {
        "id": f"record_{uuid4().hex[:8]}",
        "name": name,
        "type": (payload.record_type or "workflow_record").strip(),
        "entity": (payload.entity or "Unassigned").strip(),
        "status": "draft",
        "lane": "draft",
        "owner": (payload.owner or "").strip(),
        "due_date": (payload.due_date or "").strip(),
        "next_action": (payload.next_action or "Review the newly created work item.").strip(),
        "signal": "New work item awaiting qualification.",
        "route_tags": [payload.route.strip()] if payload.route and payload.route.strip() else [],
        "advance_requires": [],
        "created_at": now(),
    }
    state["records"].append(record)
    state["activity"].append({"event_name": "record_created", "record_id": record["id"], "user_id": actor["user_id"], "created_at": now()})
    save_state(actor["organization_id"], state)
    return {"state": state, "record": record}


@app.post("/records/{record_id}/actions")
def record_workflow_action(record_id: str, payload: WorkflowActionRequest, actor: dict[str, str] = Depends(subject)) -> dict[str, Any]:
    reject_legacy_mutation_if_executable()
    state = load_state(actor["organization_id"])
    record = next((item for item in state["records"] if item.get("id") == record_id), None)
    if record is None:
        raise HTTPException(status_code=404, detail="Record not found")
    action = payload.action.strip()
    if len(action) < 3:
        raise HTTPException(status_code=422, detail="Workflow action is required")
    event = {
        "event_name": "workflow_action_recorded",
        "record_id": record_id,
        "action": action,
        "note": (payload.note or "").strip(),
        "user_id": actor["user_id"],
        "created_at": now(),
    }
    record["last_action"] = action
    record["last_action_at"] = event["created_at"]
    state["activity"].append(event)
    save_state(actor["organization_id"], state)
    return {"state": state, "record": record, "event": event}


@app.patch("/settings")
def update_settings(payload: WorkspaceSettingsPatch, actor: dict[str, str] = Depends(subject)) -> dict[str, Any]:
    reject_legacy_mutation_if_executable()
    coordinator = payload.default_coordinator.strip()
    review_window = payload.default_review_window.strip()
    if not coordinator or not review_window:
        raise HTTPException(status_code=422, detail="Both workspace defaults are required")
